import React from "react";
import "./../../css/AppointmentsDet.css";
import withRouter from "../withRouter";

class AppointmentsDet extends React.Component {
  state = {
    appointment: null,
    loading: true,
    error: null,
  };

  componentDidMount() {
    this.getAppointment();
  }

  getAppointment = () => {
    const { id } = this.props.params;

    fetch(`http://localhost:8000/api/appointment/det/${id}`)
      .then((response) => {
        if (!response.ok) {
          throw new Error("خطا در دریافت اطلاعات نوبت");
        }

        return response.json();
      })
      .then((result) => {
        if (!result.success) {
          throw new Error(
            result.message || "اطلاعات نوبت دریافت نشد."
          );
        }

        this.setState({
          appointment: result.data.appointment,
          loading: false,
          error: null,
        });
      })
      .catch((error) => {
        console.error(error);

        this.setState({
          loading: false,
          error: error.message,
        });
      });
  };

  formatNumber = (number) => {
    return new Intl.NumberFormat("fa-IR").format(
      Number(number || 0)
    );
  };

  formatMoney = (number) => {
    return `${this.formatNumber(number)} تومان`;
  };

  formatDate = (date) => {
    if (!date) {
      return "-";
    }

    const parsedDate = new Date(date);

    if (Number.isNaN(parsedDate.getTime())) {
      return "-";
    }

    return new Intl.DateTimeFormat("fa-IR", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    }).format(parsedDate);
  };

  formatTime = (date) => {
    if (!date) {
      return "-";
    }

    const parsedDate = new Date(date);

    if (Number.isNaN(parsedDate.getTime())) {
      return "-";
    }

    return new Intl.DateTimeFormat("fa-IR", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    }).format(parsedDate);
  };

  getStatusData = (appointment) => {
    const status = appointment?.status;

    const data = {
      confirmed: {
        className: "confirmed",
        text: "تأیید شده",
        sideClass: "paid",
        sideIcon: (
          <>
            <circle cx="12" cy="12" r="10" />
            <path d="m9 12 2 2 4-4" />
          </>
        ),
        bannerClass: "confirmed-banner",
      },
      completed: {
        className: "completed",
        text: "تکمیل‌شده",
        sideClass: "paid",
        sideIcon: (
          <>
            <circle cx="12" cy="12" r="10" />
            <path d="m9 12 2 2 4-4" />
          </>
        ),
        bannerClass: "completed-banner",
      },
      cancelled: {
        className: "cancelled",
        text: "لغوشده",
        sideClass: "muted",
        sideIcon: null,
        bannerClass: "cancelled-banner",
      },
    };

    return (
      data[status] || {
        className: "completed",
        text: status || "نامشخص",
        sideClass: "muted",
        sideIcon: null,
        bannerClass: "completed-banner",
      }
    );
  };

  getPaymentStatus = (appointment) => {
    if (!appointment) {
      return {
        className: "muted",
        text: "وضعیت پرداخت نامشخص",
        icon: null,
      };
    }

    const paymentStatus = appointment.payment_status;
    const transaction = appointment.transaction;

    const paidAmount =
      transaction?.paid_amount !== undefined &&
      transaction?.paid_amount !== null
        ? Number(transaction.paid_amount)
        : Number(appointment.deposit_amount || 0);

    if (paymentStatus === "paid") {
      return {
        className: "paid",
        text: `پرداخت کامل · ${this.formatMoney(paidAmount)}`,
        icon: (
          <>
            <circle cx="12" cy="12" r="10" />
            <path d="m9 12 2 2 4-4" />
          </>
        ),
      };
    }

    if (paymentStatus === "partial") {
      return {
        className: "paid",
        text: `بیعانه پرداخت شد · ${this.formatMoney(
          paidAmount
        )}`,
        icon: (
          <>
            <circle cx="12" cy="12" r="10" />
            <path d="m9 12 2 2 4-4" />
          </>
        ),
      };
    }

    if (appointment.status === "cancelled") {
      return {
        className: "muted",
        text: "پرداختی انجام نشده",
        icon: null,
      };
    }

    return {
      className: "muted",
      text: "پرداخت نشده",
      icon: null,
    };
  };

  getServiceName = (appointment) => {
    if (!appointment) {
      return "خدمت";
    }

    if (appointment.service?.name) {
      return appointment.service.name;
    }

    if (appointment.service?.title) {
      return appointment.service.title;
    }

    return "خدمت زیبایی";
  };

  getServiceCategory = (appointment) => {
    if (!appointment) {
      return "خدمات زیبایی";
    }

    if (appointment.service?.category) {
      return appointment.service.category;
    }

    if (appointment.service?.category_name) {
      return appointment.service.category_name;
    }

    return "خدمات زیبایی";
  };

  getProviderName = (appointment) => {
    const staff = appointment?.assigned_staff;

    if (!staff) {
      return "پزشک / متخصص";
    }

    if (staff.name) {
      return staff.name;
    }

    const fullName = `${staff.first_name || ""} ${
      staff.last_name || ""
    }`.trim();

    return fullName || "پزشک / متخصص";
  };

  getProviderRole = (appointment) => {
    const staff = appointment?.assigned_staff;

    return staff.b.name;

    if (!staff) {
      return "متخصص زیبایی";
    }

    if (staff.role?.name) {
      return staff.b.name;
    }

    if (staff.role_name) {
      return staff.role_name;
    }

    return "متخصص زیبایی";
  };

  getAvatar = (appointment) => {
    const name = this.getProviderName(appointment);

    const parts = name
      .replace("دکتر", "")
      .trim()
      .split(/\s+/)
      .filter(Boolean);

    if (parts.length >= 2) {
      return `${parts[0].charAt(0)}‌${parts[1].charAt(0)}`;
    }

    if (parts.length === 1) {
      return parts[0].substring(0, 2);
    }

    return "د";
  };

  getRemainingAmount = (appointment) => {
    if (!appointment) {
      return 0;
    }

    const transaction = appointment.transaction;

    if (
      transaction?.remaining_amount !== undefined &&
      transaction?.remaining_amount !== null
    ) {
      return Number(transaction.remaining_amount);
    }

    const amount = Number(appointment.amount || 0);
    const paidAmount = Number(appointment.deposit_amount || 0);

    return Math.max(amount - paidAmount, 0);
  };

  renderPayment = (appointment) => {
    const amount = Number(appointment.amount || 0);
    const transaction = appointment.transaction;

    const paidAmount =
      transaction?.paid_amount !== undefined &&
      transaction?.paid_amount !== null
        ? Number(transaction.paid_amount)
        : Number(appointment.deposit_amount || 0);

    const remainingAmount = this.getRemainingAmount(appointment);

    return (
      <div className="pay-card">
        <div className="pay-title">خلاصه پرداخت</div>

        <div className="pay-row">
          <span>جمع خدمت</span>
          <span>{this.formatMoney(amount)}</span>
        </div>

        {paidAmount > 0 && (
          <div className="pay-row">
            <span>
              {appointment.payment_status === "paid"
                ? "پرداخت‌شده"
                : "بیعانه پرداخت‌شده"}
            </span>

            <span className="neg">
              −{this.formatMoney(paidAmount)}
            </span>
          </div>
        )}

        {remainingAmount > 0 && (
          <div className="pay-row total">
            <span>مانده قابل پرداخت</span>
            <span>{this.formatMoney(remainingAmount)}</span>
          </div>
        )}

        {appointment.payment_status === "paid" &&
          remainingAmount === 0 && (
            <div className="pay-row total">
              <span>وضعیت پرداخت</span>
              <span>تسویه کامل</span>
            </div>
          )}

        {appointment.payment_status === "unpaid" && (
          <div className="pay-row total">
            <span>وضعیت پرداخت</span>
            <span>پرداخت نشده</span>
          </div>
        )}
      </div>
    );
  };

  renderActions = (appointment) => {
    if (!appointment) {
      return null;
    }

    if (appointment.status !== "confirmed") {
      return null;
    }

    return (
      <div className="d-actions">
        <button
          className="act-btn"
          onClick={() =>
            console.log("تغییر زمان نوبت", appointment.id)
          }
        >
          <svg
            width="16"
            height="16"
